// ============================================
// EVOLUTION API PAYLOAD NORMALIZER
// Evolution sends: { event, instance, data: { key, pushName, message, messageType, ... } }
// With Base64 enabled, media comes as data.base64 or data.media
// ============================================
const payload = items[0].json.body;

// Solo procesamos mensajes entrantes (no los que enviamos nosotros)
const event = payload.event || '';
if (event !== 'messages.upsert') {
  return [{ json: { skip: true, reason: 'not a message event', event } }];
}

const data = payload.data || {};
const key = data.key || {};

// Ignorar mensajes enviados por nosotros
if (key.fromMe === true) {
  return [{ json: { skip: true, reason: 'fromMe message' } }];
}

// Extraer número limpio (viene como 'user@example.com' o 'user@example.com')
const remoteJid = key.remoteJid || '';
const phone = remoteJid.replace(/@s\.whatsapp\.net|@c\.us|@g\.us/g, '');

// Ignorar mensajes de grupos (tienen @g.us)
if (remoteJid.includes('@g.us')) {
  return [{ json: { skip: true, reason: 'group message' } }];
}

const senderName = data.pushName || 'Customer';
const messageType = data.messageType || 'conversation';
const instanceName = payload.instance || 'cifral-test';

// Detectar tipo de mensaje
const isAudio = messageType === 'audioMessage' || messageType === 'audio';
const isText = messageType === 'conversation' || messageType === 'extendedTextMessage';

// Extraer texto
let text = '';
if (isText) {
  text = data.message?.conversation 
    || data.message?.extendedTextMessage?.text 
    || '';
}

// Audio viene como base64 en el payload (porque activamos Webhook Base64)
// Evolution lo pone en data.base64 o data.message.base64
const audioBase64 = isAudio 
  ? (data.base64 || data.media || data.message?.base64 || '')
  : '';

const messageId = key.id || String(Date.now());
const timestamp = data.messageTimestamp 
  ? new Date(data.messageTimestamp * 1000).toISOString()
  : new Date().toISOString();

return [{
  json: {
    skip: false,
    phone,
    sender_name: senderName,
    message_type: isAudio ? 'voice' : 'text',
    text,
    audio_base64: audioBase64,
    message_id: messageId,
    timestamp,
    instance_name: instanceName,
    raw_type: messageType
  }
}];

// ============================================
// PREPARE AUDIO FOR OPENAI TRANSCRIPTION
// Evolution sends audio as base64 when 'Webhook Base64' is enabled
// We need to convert it to binary for the OpenAI node
// ============================================
const base64Audio = items[0].json.audio_base64 || '';

if (!base64Audio) {
  // Si no hay base64, devuelve texto vacío para no romper el flujo
  return [{ json: { ...items[0].json, text: '[audio no disponible]' } }];
}

// Limpiar el base64 por si viene con el prefijo data:audio/ogg;base64,
const cleanBase64 = base64Audio.replace(/^data:audio\/[^;]+;base64,/, '');

// Convertir a buffer binario
const buffer = Buffer.from(cleanBase64, 'base64');

return [{
  json: { ...items[0].json },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'audio/ogg',
      fileName: 'audio.ogg'
    }
  }
}];

parameters.inputSchema:
={
  "type": "object",
  "properties": {
    "intent": {
      "type": "string",
      "description": "Main intent of the message. Use: interested, not_interested, asking_question, wrong_person, inquiry_price, inquiry_product, inquiry_schedule, inquiry_availability, request_quote, request_contact, greeting, other"
    },
    "reply_sentiment": {
      "type": "string",
      "description": "Sentiment toward a B2B outreach offer. 'positive': interested, curious, open to a call, asking for more info. 'negative': not interested, asks to stop, wrong person, dismissive. 'neutral': unclear or cannot be determined. Use 'neutral' for new inbound contacts who were not previously contacted."
    },
    "product_mentioned": {
      "type": "string",
      "description": "Product or service mentioned by the person, if any. Empty if none."
    },
    "urgency": {
      "type": "string",
      "description": "Urgency level: high, medium, low, none"
    },
    "needs_human": {
      "type": "boolean",
      "description": "True if the person asks about pricing, wants a quote, wants to speak with someone, shows buying interest, or expresses frustration. Always true for price-related questions."
    }
  },
  "required": ["intent", "reply_sentiment", "needs_human"]
}

