// ============================================
// BUILD CONTEXT FOR AI AGENT
// Pulls: message data, business KB, lead context from Notion
// ============================================

const userMessage = $('Transcribe Audio1').isExecuted 
  ? $('Transcribe Audio1').first().json.text 
  : $('Detect Message Type1').first().json.text || '';

const userName     = $('Detect Message Type1').first().json.sender_name || 'Customer';
const userPhone    = $('Detect Message Type1').first().json.phone || '';
const messageType  = $('Detect Message Type1').first().json.message_type || 'text';
const instanceName = $('Detect Message Type1').first().json.instance_name || 'cifral-v1';

// --- Knowledge base ---
const businessInfoItems = $('Read Business Info1').all();
const productsItems     = $('Read Products1').all();
const faqsItems         = $('Read FAQs1').all();

const business = {};
businessInfoItems.forEach(item => {
  const d = item.json;
  if (d.business_info && d.value) business[d.business_info] = d.value;
});

const productList = productsItems
  .filter(i => i.json.product_id)
  .map(i => {
    const p = i.json;
    const available = p.available === 'SI' ? 'AVAILABLE' : 'NOT AVAILABLE';
    const highlight = p.highlight ? ` [${p.highlight}]` : '';
    return `- ${p.name} (${p.product_id}): ${p.description}\n  Status: ${available}\n  Category: ${p.category}${highlight}`;
  })
  .join('\n\n');

const faqList = faqsItems
  .filter(i => i.json.question)
  .map(i => `Q: ${i.json.question}\nA: ${i.json.answer}\nCategory: ${i.json.category}`)
  .join('\n\n');

// --- Extractor output ---
const extractor = $('Information Extractor1').first().json.output || {};

// --- Notion lead context (from Check Leads node) ---
const notionLead = $('Check Leads1').first().json;

const outreach_context = notionLead.is_known_lead
  ? {
      is_outreach_lead:    true,
      personalization_note: notionLead.personalization_note || '',
      pain_point:          notionLead.pain_point || '',
      lead_status:         notionLead.lead_status || '',
      notion_page_id:      notionLead.page_id || ''
    }
  : {
      is_outreach_lead: false,
      notion_page_id:   notionLead.page_id || ''
    };

return [{
  json: {
    context: {
      business_name:        business.business_name || 'Your Business Name',
      business_description: business.business_description || '',
      phone:                business.phone || '',
      email:                business.email || '',
      hours:                business.hours || '',
      coverage_area:        business.coverage_area || '',
      response_tone:        business.response_tone || 'professional and friendly',
      language:             business.language || 'same language as customer',
      products:             productList || 'No products configured',
      faqs:                 faqList || 'No FAQs configured'
    },
    user: {
      name:               userName,
      phone:              userPhone,
      message:            userMessage,
      message_type:       messageType,
      instance_name:      instanceName,
      intent:             extractor.intent || 'unknown',
      product_mentioned:  extractor.product_mentioned || 'none',
      reply_sentiment:    extractor.reply_sentiment || 'neutral',
      urgency:            extractor.urgency || 'none',
      needs_human:        extractor.needs_human || false,
      outreach_context
    }
  }
}];

