// Strip markdown formatting from AI response
let text = $input.item.json.output || '';

// Remove bold/italic
text = text.replace(/\*\*(.*?)\*\*/g, '$1');
text = text.replace(/\*(.*?)\*/g, '$1');
text = text.replace(/_(.*?)_/g, '$1');

// Replace em dashes with comma
text = text.replace(/ — /g, ', ');
text = text.replace(/—/g, ', ');

// Remove markdown headers
text = text.replace(/^#{1,3}\s+/gm, '');

// Clean up extra blank lines (max 1)
text = text.replace(/\n{3,}/g, '\n\n');

return { json: { ...$input.item.json, output: text.trim() } };

// ============================================
// NORMALIZE AND LOOK MATCH — Get Lead Early
// Reads n8n Notion node output (flattened: property_*)
// ============================================

const webhookPhone = $('Detect Message Type1').first().json.phone;
const notionLeads  = $input.all();

const messageData = {
  phone:         $('Detect Message Type1').first().json.phone,
  sender_name:   $('Detect Message Type1').first().json.sender_name,
  message_type:  $('Detect Message Type1').first().json.message_type,
  instance_name: $('Detect Message Type1').first().json.instance_name,
  text: $('Sentiment Analysis1').first().json.text
        || $('Detect Message Type1').first().json.text
        || ''
};

const normalize = (p) => {
  let n = String(p || '').replace(/[^0-9]/g, '');
  // Add country-specific phone normalization here if needed
  return n;
};

const normalizedWebhook = normalize(webhookPhone);

const match = notionLeads.find(item => {
  const notionPhone = normalize(item.json.property_phone || '');
  return notionPhone.length >= 10 && notionPhone === normalizedWebhook;
});

if (match) {
  return [{
    json: {
      ...messageData,
      is_known_lead:        true,
      matched:              true,
      page_id:              match.json.id || '',
      bot_status:           match.json.property_wa_chat_bot_status || 'Active',
      lead_status:          match.json.property_status || '',
      personalization_note: match.json.property_ai_personalization_note || '',
      pain_point:           match.json.property_ai_notes || '',
    }
  }];
} else {
  return [{
    json: {
      ...messageData,
      is_known_lead: false,
      matched:       false,
      page_id:       '',
      bot_status:    'Active',
    }
  }];
}
